def connect(root) -> list:
    if not root:
        return []
    if isinstance(root, list):
        root = list_to_tree(root)
    if not root:
        return []
    res = []
    queue = [root]
    while queue:
        level_len = len(queue)
        for i in range(level_len):
            node = queue.pop(0)
            res.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        res.append('#')
    return res

reference_solution.javascript:
function connect(root) {
  if (!root) return [];
  let treeRoot = root;
  if (Array.isArray(root)) {
    treeRoot = listToTree(root);
  }
  if (!treeRoot) return [];
  const res = [];
  const queue = [treeRoot];
  while (queue.length > 0) {
    const len = queue.length;
    for (let i = 0; i < len; i++) {
      const node = queue.shift();
      res.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    res.push('#');
  }
  return res;
}
